/bin/bash -lc "python - <<'PY'
import collections, re, json
sam='/workspace/galaxy_phase_alignments.sam'
CIGAR_RE=re.compile(r'(\\d+)([MIDNSHP=X])')

def parse_alignment(pos,cigar,seq):
    ref=pos; read=0; bases={}; deletions=set(); insertions={}; noins=set(); prev=None; last=None
    for n_s,op in CIGAR_RE.findall(cigar):
        n=int(n_s)
        if op in 'M=X':
            for i in range(n):
                p=ref+i; bases[p]=seq[read+i]
                if prev==p-1: noins.add(prev)
                prev=p; last=p
            ref+=n; read+=n
        elif op=='I':
            if last is not None: insertions[last]=seq[read:read+n]
            read+=n; prev=None
        elif op in 'DN':
            if op=='D':
                for p in range(ref,ref+n): deletions.add(p)
            ref+=n; prev=None; last=None
        elif op=='S': read+=n
        elif op in 'HP': pass
        else: raise Exception(op)
    return bases,deletions,insertions,noins

fragments=collections.defaultdict(list); chrom_counts=collections.Counter(); spans=collections.defaultdict(lambda:[10**18,0])
base_counts=collections.defaultdict(collections.Counter); del_counts=collections.defaultdict(int); ins_counts=collections.defaultdict(collections.Counter); noins_counts=collections.defaultdict(int)
records=0
with open(sam) as f:
    for line in f:
        if not line.strip() or line.startswith('@'): continue
        fields=line.rstrip('\\n').split('\\t')
        if len(fields)<11: continue
        qname,flag_s,rname,pos_s,mapq_s,cigar=fields[:6]
        flag=int(flag_s)
        if flag & 2308 or rname=='*' or cigar=='*': continue
        seq=fields[9].upper(); pos=int(pos_s)
        parsed=parse_alignment(pos,cigar,seq)
        records+=1; chrom_counts[rname]+=1; fragments[qname].append((rname,parsed))
        bases,dels,ins,noins=parsed
        if bases or dels:
            lo=min(list(bases)+list(dels)); hi=max(list(bases)+list(dels)); spans[rname][0]=min(spans[rname][0],lo); spans[rname][1]=max(spans[rname][1],hi)
        for p,b in bases.items(): base_counts[(rname,p)][b]+=1
        for p in dels: del_counts[(rname,p)]+=1
        for p,s in ins.items(): ins_counts[(rname,p)][s]+=1
        for p in noins: noins_counts[(rname,p)]+=1

variants=[]
for (chrom,pos),counts in base_counts.items():
    total=sum(counts.values()); major=[(a,c) for a,c in counts.most_common() if a in 'ACGT']
    if len(major)>=2 and major[0][1]>=20 and major[1][1]>=20 and major[1][1]/total>=0.20:
        variants.append((chrom,'SNP',pos,tuple(sorted([major[0][0],major[1][0]]))))
for (chrom,pos),dcount in del_counts.items():
    counts=base_counts.get((chrom,pos),collections.Counter()); total=dcount+sum(counts.values())
    if dcount>=20 and total and dcount/total>=0.20:
        base=counts.most_common(1)[0][0] if counts else 'N'
        variants.append((chrom,'DEL',pos,tuple(sorted([base,'D']))))
for (chrom,pos),counts in ins_counts.items():
    one=[(s,c) for s,c in counts.items() if len(s)==1]
    if one:
        seq,icount=max(one,key=lambda x:x[1]); total=icount+noins_counts.get((chrom,pos),0)
        if icount>=20 and total and icount/total>=0.20:
            base=base_counts.get((chrom,pos),collections.Counter()).most_common(1)[0][0]
            variants.append((chrom,'INS',pos,tuple(sorted([base,'I']))))
chrom_order={c:i for i,(c,_) in enumerate(chrom_counts.most_common())}
variants=sorted(set(variants), key=lambda v:(chrom_order.get(v[0],999999),v[2],0 if v[1]"'!='"'INS' else 1,v[1]))

def allele(parsed_reads,var):
    chrom,kind,pos,alleles=var
    for bases,dels,ins,noins in parsed_reads:
        if kind=='SNP':
            b=bases.get(pos)
            if b in alleles: return b
        elif kind=='DEL':
            if pos in dels: return 'D'
            b=bases.get(pos)
            if b in alleles: return b
        elif kind=='INS':
            if pos in ins and len(ins[pos])==1: return 'I'
